changeSet.sql:
ALTER TABLE public.approval_tickets DROP CONSTRAINT IF EXISTS approval_tickets_status_check;
ALTER TABLE public.approval_tickets ADD CONSTRAINT approval_tickets_status_check
    CHECK(status IN ('PENDING','RETURNED','APPROVED','REJECTED','PARTIALLY_REJECTED','CANCELLED'));

CREATE TABLE public.order_item_approvals (
    id uuid PRIMARY KEY,
    ticket_id uuid NOT NULL REFERENCES public.approval_tickets(id) ON DELETE CASCADE,
    order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
    order_item_id uuid NOT NULL REFERENCES public.order_items(id) ON DELETE CASCADE,
    product_id uuid NOT NULL REFERENCES public.products(id),
    manager_id uuid REFERENCES public.profiles(id),
    status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')),
    reviewed_by uuid REFERENCES public.profiles(id),
    reason text,
    reviewed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX idx_item_approvals_ticket ON public.order_item_approvals(ticket_id);
CREATE INDEX idx_item_approvals_order ON public.order_item_approvals(order_id);
CREATE INDEX idx_item_approvals_manager ON public.order_item_approvals(manager_id);
